            e.preventDefault();
            e.stopPropagation();
            if (menu) {
                var isOpen = menu.classList.contains('sidemenu-on');
                if (isOpen) {
                    menu.classList.remove('sidemenu-on');
                    menu.classList.add('sidemenu-off');
                    document.body.classList.remove('sidemenu-active', 'mobile_menu_active');
                } else {
                    menu.classList.remove('sidemenu-off');
                    menu.classList.add('sidemenu-on');
                    document.body.classList.add('sidemenu-active', 'mobile_menu_active');
                }
            }
        }
        var closeBtn = e.target.closest('#menu-icon-close, .sidemenu-close, .sidemenu-cover');
        if (closeBtn) {
            e.preventDefault();
            if (menu) {
                menu.classList.remove('sidemenu-on');
                menu.classList.add('sidemenu-off');
                document.body.classList.remove('sidemenu-active', 'mobile_menu_active');
            }
        }
    });
});
</script>
</body></html>